from pathlib import Path

path = Path('/home/ubuntu/stargatewars/game.php')
text = path.read_text()
start = text.index('function settlementPage()')
end = text.index('function mothershipPage()', start)
new_function = r'''function settlementPage(){const u=state.settlement||{},p=u.power||{},fields=Array.isArray(u.fields)?u.fields:[],catalog=Array.isArray(u.building_classes)?u.building_classes:[],colony=u.colony||{},settlement=u.settlement||{},colonyId=Number(colony.id||settlement.colony_id||0),key=String(settlement.settlement_key||'planet:1'),locationType=String(settlement.location_type||'planet'),csrf=state.csrf||'',balance=Number(p.balance||0),efficiency=Math.round(Number(p.efficiency||1)*100),queues=Array.isArray(u.queues)?u.queues:[],options=(catalog.filter(x=>!x.buildable_on||x.buildable_on==='both'||x.buildable_on===locationType).map(x=>'<option value="'+esc(x.building_key)+'">'+esc(x.name)+' · '+esc(x.building_class)+'</option>').join(''));const kindLabel=k=>String(k||'standard').replace(/[-_]/g,' ');const kindClass=k=>String(k||'standard').replace(/[^a-z0-9_-]/gi,'').toLowerCase()||'standard';const queueRows=queues.length?queues.map(q=>'<div class="settlement-queue-item"><div><strong>'+esc(q.name||q.building_key||'Construction')+'</strong><small>'+esc(q.status||'building')+' · '+esc(q.level_before||0)+' → '+esc(q.level_after||0)+'</small></div><div class="queue-time">'+esc(q.completes_at||'queued')+'</div></div>').join(''):'<div class="empty">No active construction queue.</div>';const fieldRows=fields.length?fields.map(f=>{const b=f.building,kind=kindClass(f.field_kind),label=kindLabel(f.field_kind),powerOut=Number(b&&b.power_output||0),powerIn=Number(b&&b.power_consumption||0);return '<article class="settlement-field '+(b?'occupied':'vacant')+' field-'+kind+'"><div class="field-head"><div><span class="field-index">FIELD '+fmt(f.field_index)+'</span><strong>'+esc(label)+'</strong></div><span class="field-state '+(b?'online':'open')+'">'+(b?'ONLINE':'OPEN')+'</span></div><div class="field-orbit"><span class="field-orbit-dot"></span><span>'+esc(locationType.toUpperCase())+' GRID</span></div><div class="field-body">'+(b?'<h3>'+esc(b.name||b.building_key)+'</h3><p class="field-meta">Level '+fmt(b.level)+' · '+(powerOut>=0?'+':'')+fmt(powerOut)+' PWR · -'+fmt(powerIn)+' DRAW</p><div class="field-meter"><i style="width:'+Math.min(100,Math.max(12,Number(b.condition_value||1)*100))+'%"></i></div><form method="post" action="actions/game.php" class="field-action-form">'+csrf+'<input type="hidden" name="action" value="settlement_demolish"><input type="hidden" name="redirect" value="settlement"><input type="hidden" name="colony_id" value="'+fmt(colonyId)+'"><input type="hidden" name="field_index" value="'+fmt(f.field_index)+'"><button class="button field-button" type="submit">Demolish</button></form>':'<p class="field-empty">Vacant field. Placement, prerequisites, cost, and queue capacity are verified by the server.</p><form method="post" action="actions/game.php" class="field-action-form">'+csrf+'<input type="hidden" name="action" value="settlement_build"><input type="hidden" name="redirect" value="settlement"><input type="hidden" name="colony_id" value="'+fmt(colonyId)+'"><input type="hidden" name="field_index" value="'+fmt(f.field_index)+'"><select name="building_key" required><option value="">Select structure</option>'+options+'</select><button class="button dark field-button" type="submit" '+(colonyId<1?'disabled':'')+'>Queue build</button></form>')+'</div></article>';}).join(''):'<div class="empty">No fields are initialized for this settlement.</div>';const libraryRows=catalog.map(x=>'<tr><td><strong>'+esc(x.name)+'</strong><small>'+esc(x.building_key)+'</small></td><td><span class="library-class">'+esc(x.building_class)+'</span></td><td>'+esc(x.buildable_on||'both')+'</td><td><span class="power-positive">+'+fmt(x.base_power_output||0)+'</span> <span class="power-negative">−'+fmt(x.base_power_consumption||0)+'</span></td><td>'+esc(x.prerequisite_key||'none')+' <small>'+fmt(x.prerequisite_level||0)+'</small></td></tr>').join('');document.getElementById('section').textContent='PLANETS';document.getElementById('title').textContent='Settlement & Power Grid';document.getElementById('description').textContent='Planetary and lunar fields, modular infrastructure, and server-balanced power distribution.';document.getElementById('content').innerHTML=`<div class="settlement-shell"><section class="settlement-hero"><div><div class="eyebrow">SETTLEMENT CONTROL / ${esc(locationType.toUpperCase())}</div><h2>${esc(key)}</h2><p>Build a living planetary grid from resource fields to cities, research cores, and shipyards. Every command is authenticated, ownership-checked, and committed transactionally.</p></div><div class="hero-status"><span class="status-pulse"></span><strong>${balance<0?'BROWNOUT RISK':'GRID ONLINE'}</strong><small>${balance<0?'Mitigation floor active':'Server telemetry synchronized'}</small></div></section><section class="settlement-metrics"><div class="settlement-metric generation"><span>POWER OUTPUT</span><strong>${fmt(p.output||0)}</strong><small>Active generation</small></div><div class="settlement-metric load"><span>POWER DRAW</span><strong>${fmt(p.consumption||0)}</strong><small>Infrastructure load</small></div><div class="settlement-metric ${balance<0?'danger':'stable'}"><span>GRID BALANCE</span><strong>${balance>=0?'+':''}${fmt(balance)}</strong><small>${balance<0?'Brownout risk':'Power balanced'}</small></div><div class="settlement-metric"><span>EFFICIENCY</span><strong>${efficiency}%</strong><small>Minimum floor 25%</small></div></section><section class="settlement-main-grid"><div class="settlement-panel power-panel"><div class="panel-kicker">POWER FLOW</div><div class="panel-title-row"><div><h2>Grid balance</h2><p>Generation and consumption resolve from completed infrastructure.</p></div><span class="grid-badge ${balance<0?'warning':'success'}">${balance<0?'BROWNOUT':'NOMINAL'}</span></div><div class="power-flow"><div class="power-node"><span class="node-icon">GEN</span><strong>${fmt(p.output||0)}</strong><small>Generation</small></div><div class="power-connector"><i style="width:${Math.min(100,Math.max(8,efficiency))}%"></i></div><div class="power-core"><span class="core-ring">${efficiency}%</span><strong>GRID</strong><small>Efficiency</small></div><div class="power-connector reverse"><i style="width:${Math.min(100,Math.max(8,efficiency))}%"></i></div><div class="power-node draw"><span class="node-icon">LOAD</span><strong>${fmt(p.consumption||0)}</strong><small>Consumption</small></div></div><div class="power-caption"><span><b></b> Stable distribution</span><span>Output − draw = ${balance>=0?'+':''}${fmt(balance)} PWR</span></div></div><aside class="settlement-panel command-panel"><div class="panel-kicker">QUEUE CONTROL</div><h2>Construction operations</h2><p>Resolve completed work or review active construction. Queue capacity and costs remain server-authoritative.</p><form method="post" action="actions/game.php">${csrf}<input type="hidden" name="action" value="settlement_process"><input type="hidden" name="redirect" value="settlement"><button class="button dark full-button" type="submit">Process due construction</button></form><div class="command-rule"></div><div class="command-stat"><span>Active queue</span><strong>${fmt(queues.length)}</strong></div><div class="command-stat"><span>Settlement</span><strong>${esc(locationType)}</strong></div><span class="badge good">SERVER VERIFIED</span></aside></section><section class="settlement-panel field-panel"><div class="panel-title-row"><div><div class="panel-kicker">FIELD GRID</div><h2>Modular infrastructure</h2><p>Assign fields to a role, then grow the settlement from libraries to cities and shipyards.</p></div><div class="field-legend"><span><i class="legend-dot online"></i>Occupied</span><span><i class="legend-dot open"></i>Available</span></div></div><div class="settlement-grid">${fieldRows}</div></section><section class="settlement-bottom-grid"><div class="settlement-panel queue-panel"><div class="panel-title-row"><div><div class="panel-kicker">ACTIVE WORK</div><h2>Construction queue</h2></div><span class="grid-badge ${queues.length?'warning':'success'}">${queues.length?fmt(queues.length)+' ACTIVE':'EMPTY'}</span></div><div class="settlement-queue-list">${queueRows}</div></div><div class="settlement-panel library-panel"><div class="panel-kicker">BUILDING LIBRARY</div><h2>Libraries → cities → shipyards</h2><p>Catalog filtered for this ${esc(locationType)}. Placement, alignment, prerequisites, resources, and queue capacity are checked on the server.</p><div class="library-summary"><strong>${fmt(catalog.length)}</strong><span>available structure designs</span></div></div></section><section class="settlement-panel library-table-panel"><div class="panel-title-row"><div><div class="panel-kicker">STRUCTURE CATALOG</div><h2>Power and prerequisite matrix</h2></div><span class="badge">READ ONLY</span></div><table class="table"><thead><tr><th>Structure</th><th>Class</th><th>Placement</th><th>Power profile</th><th>Prerequisite</th></tr></thead><tbody>${libraryRows||'<tr><td colspan="5">No structures available.</td></tr>'}</tbody></table></section><section class="settlement-contract"><span class="contract-mark">AUTH</span><div><strong>SERVER-AUTHORITATIVE SETTLEMENT</strong><p>Actions: <code>settlement_build</code> · <code>settlement_demolish</code> · <code>settlement_process</code>. Ownership, field alignment, prerequisites, resource balances, queue capacity, and transaction state are verified before mutation.</p></div><span class="badge good">ONLINE</span></section></div>`}
'''
path.write_text(text[:start] + new_function + text[end:])
print('settlement renderer replaced')
